using UnityEngine;using UnityEditor;
namespace LWS.TruckSports.Editor {
public static class SportsDrivingViewsAuthoring {
 public static SportsDrivingViews Install(SportsEventSession match,SportsEventTruck[] trucks,SportsEventCamera broadcast,string folder){var existing=match.GetComponent<SportsDrivingViews>();if(existing!=null)return existing;var rally=match.gameObject.AddComponent<SportsRallyViews>();rally.session=match;rally.trucks=trucks;rally.broadcast=broadcast;rally.views=new SportsEventCamera[4];var view=match.gameObject.AddComponent<SportsDrivingViews>();view.session=match;view.rally=rally;view.cabs=new Transform[4];view.looks=new SportsCabLook[4];for(int i=0;i<4;i++){var camera=SportsEventAuthoring.Camera(match.Title+" local driving view "+i);SportsRallyAuthoring.TuneCamera(camera);camera.view.enabled=false;rally.views[i]=camera;SportsChaosAuthoring.Cab(camera.view,folder,i);view.cabs[i]=camera.transform.Find("Driver seat interior");view.looks[i]=camera.gameObject.AddComponent<SportsCabLook>();view.cabs[i].gameObject.SetActive(false);}view.modeLabel=SportsUIAuthoring.Button(match.menus.pages[0].transform,"VIEW: SHARED ARENA","drivingview",new Vector2(0,305),new Vector2(650,44)).normalTextObj;SportsUIAuthoring.Button(match.menus.pages[3].transform,"CHANGE DRIVING VIEW","drivingview",new Vector2(0,-285),new Vector2(650,54));SportsBroadcastAuthoring.ApplyScene();EditorUtility.SetDirty(match);return view;}
}
}
